import torch


def run(input, output_size, align_corners):
    return torch.ops.aten.upsample_trilinear3d.default(
        input, output_size, align_corners, None, None, None
    )


def run_correctness(input, output_size, align_corners):
    output = torch.ops.aten.upsample_trilinear3d.default(
        input.float(), output_size, align_corners, None, None, None
    )
    return output.to(input.dtype)
